import {productVolume} from './kinetic-models.js?v=20261023-physicscomplete01';
const text=(x,y,s,size=15)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="currentColor" font-family="sans-serif" font-size="${size}">${s}</text>`;
export function rateFigure({kind='rate-compare',plot=null,tilt=4,training=false}={}){const tangent=kind==='rate-tangent',isplot=kind==='rate-plot',maxT=tangent&&!training?80:60,maxV=tangent?100:80,x=t=>65+t/maxT*330,y=v=>245-v/maxV*195;const total=tangent&&!training?80:60,duration=tangent&&!training?80:60;
let art=`<path d="M65 40V245H405" stroke="currentColor" fill="none"/>${text(225,20,'Gas volume / cm³',17)}${text(235,295,'Time / s',17)}`;
for(let t=0;t<=maxT;t+=20)art+=`<path d="M${x(t)} 245v5" stroke="currentColor"/>${text(x(t),269,t)}`;
for(let v=0;v<=maxV;v+=20)art+=`<path d="M60 ${y(v)}H405" stroke="currentColor" stroke-opacity=".12"/>${text(40,y(v)+5,v)}`;
const curve=(d,color,dash='')=>`<path d="${Array.from({length:61},(_,i)=>{const t=i/60*maxT;return (i?'L':'M')+x(t)+' '+y(productVolume(t,total,d));}).join(' ')}" stroke="${color}" stroke-width="3" fill="none" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
let desc='';if(isplot){desc='Plot gas-volume readings at20,40 and60 seconds from the supplied table.';art+=[20,40,60].map(t=>{const raw=plot?.['p'+t];if(String(raw??'').trim()===''||!Number.isFinite(Number(raw)))return '';const v=Math.max(0,Math.min(80,Number(raw)));return `<circle cx="${x(t)}" cy="${y(v)}" r="5" fill="#ed8b78"/>`;}).join('');art+=`<circle cx="${x(0)}" cy="${y(0)}" r="5" fill="#ed8b78"/>`;}else if(tangent){art+=curve(duration,'#ed8b78');const contact=training?30:40,value=productVolume(contact,total,duration),slope=training?Number(tilt)/4:1,lo=contact-20,hi=contact+20,lv=value-20*slope,hv=value+20*slope;art+=`<path d="M${x(lo)} ${y(lv)}L${x(hi)} ${y(hv)}" stroke="currentColor" stroke-dasharray="6 4" stroke-width="2"/><circle cx="${x(contact)}" cy="${y(value)}" r="5" fill="currentColor"/>`;desc=`Product-volume curve with a straight line anchored at${contact} seconds. `;if(!training){art+=`<circle cx="${x(lo)}" cy="${y(lv)}" r="4" fill="currentColor"/><circle cx="${x(hi)}" cy="${y(hv)}" r="4" fill="currentColor"/>${text(x(lo)+25,y(lv)+22,'(20,40)',13)}${text(x(hi)-25,y(hv)-12,'(60,80)',13)}`;desc+='Tangent points(20 seconds,40 cubic centimetres) and(60 seconds,80 cubic centimetres).';}else desc+='Adjust the line direction; slope is not supplied as an answer.';}else{art+=curve(40,'#ed8b78')+curve(60,'#b7c8d6','6 4')+text(x(15),y(productVolume(15,60,40))-15,'A',18)+text(x(30)+12,y(productVolume(30))-0,'B',18);desc='Gas volume versus time. At times0,20,40,60 seconds, solid A has volumes0,45,60,60 cubic centimetres; dashed B has volumes0,33.33,53.33,60. Curves are smooth between these coordinates.';}
return `<svg class="profile-figure" viewBox="0 0 460 310" role="img" aria-label="${desc}">${art}</svg>`;}
export function catalystFigure({peak=65}={}){const y=v=>250-v*2,R=y(40),P=y(25),T=y(Number(peak));return `<svg class="profile-figure" viewBox="0 0 460 310" role="img" aria-label="Two reaction pathways share reactant energy40 and product energy25 symbolic units. Solid pathway peak90; dashed comparison peak${peak}. Same endpoint levels, different peaks."><path d="M45 25V265H430" stroke="currentColor" fill="none"/>${text(230,298,'Reaction progress',17)}${text(55,15,'Energy',16)}<path d="M65 ${R}H120C165 ${R} 180 70 230 70S305 ${P} 345 ${P}H395" stroke="#b7c8d6" stroke-width="3" fill="none"/><path d="M65 ${R}H120C165 ${R} 180 ${T} 230 ${T}S305 ${P} 345 ${P}H395" stroke="#ed8b78" stroke-width="3" stroke-dasharray="6 4" fill="none"/>${text(95,R-13,'Reactants',14)}${text(360,P+22,'Products',14)}${text(245,55,'Solid',14)}${text(245,T+22,'Dashed',14)}</svg>`;}
